const rowId = (index: number) =>
  `b61e8c34-1f7a-4d92-a5c0-8e3b2f9d2${String(index).padStart(3, '0')}`;

const fresh = (run: Run) => {
  const known = new Set(seeded.map((_, index) => rowId(index)));
  return (run.apps?.notion?.pages ?? []).filter(
    (page) => page.database === ids.recipes && !page.archived && !known.has(page.id),
  );
};

const recipe = (run: Run) =>
  fresh(run).find((page) => plain(page.title).includes('bacalhau')) ?? fresh(run)[0];

export default scenario({
  id: 'notion-save-recipe-from-email',
  title: 'Save the recipe Mum emailed me to my Recipes database in Notion',
  capabilities: ['apps'],
  tier: 'release',
  calibration: 'pending',
  complexity: 'medium',
  stance: 'regression',
  seconds: 600,
  user: {
    approve: (action) => !/SEND|REPLY|FORWARD|TRASH/.test(action),
    persona:
      'You are Alex Rivera. Your mum is Maria Rivera (maria.rivera@familia.example.net); she signs her emails "Mum". She emailed you her bacalhau à Brás recipe this week. Your recipes live in the Notion database called Recipes. Any sensible tags and source are fine.',
  },
  world(clock) {
    const now = clock.now();
    const databases: NotionDatabase[] = [
      {
        id: ids.recipes,
        title: 'Recipes',
        parent: ids.home,
        schema: {
          Name: { type: 'title' },
          Source: { type: 'rich_text' },
          Tags: {
            type: 'multi_select',
            options: ['Portuguese', 'Spanish', 'Fish', 'Meat', 'Vegetarian', 'Dessert', 'Quick'],
          },
        },
        rows: seeded.map((row, index) => ({
          id: rowId(index),
          properties: { ...row },
          markdown: `Recipe from ${row.Source}.`,
          edited: daysAgo(now, 10 + index * 7),
        })),
      },
    ];
    return {
      apps: createApps(owner, {
        gmail: gmail(owner, mailbox(now), clock.now),
        notion: notion(
          owner,
          {
            pages: [
              {
                id: ids.home,
                title: 'Home',
                markdown: 'Personal workspace.\n- Recipes',
                edited: daysAgo(now, 30),
              },
            ],
            databases,
          },
          clock.now,
        ),
      }),
    };
  },
  async play(session) {
    await session.say('Save the recipe Mum emailed me to my Recipes database in Notion.');
  },
  evidence: (run) =>
    `Mum (Maria Rivera) emailed the recipe "Bacalhau à Brás" with ingredients salted cod, potatoes, eggs, onions, garlic, olive oil, black olives, parsley, salt and pepper, and five steps. Her earlier "Sunday lunch" email only promised the recipe; the caldo verde newsletter is not from Mum. New rows in Recipes: ${
      fresh(run)
        .map((page) => `"${page.title}" ${JSON.stringify(page.properties)}\n${page.markdown}`)
        .join('\n\n') || 'none'
    }`,
  expect() {
    return [
      check(
        'one-new-recipe-row',
        (run) => {
          const rows = fresh(run);
          return {
            pass: rows.length === 1,
            evidence: `${rows.length} new rows: ${rows.map((page) => page.title).join(', ')}`,
          };
        },
        { failure: 'incomplete' },
      ),
      check(
        'row-titled-bacalhau-a-bras',
        (run) => {
          const rows = fresh(run);
          return {
            pass: rows.some((page) => plain(page.title).includes('bacalhau')),
            evidence: `${rows.length} new rows: ${rows.map((page) => page.title).join(', ')}`,
          };
        },
        {
          failure: 'incomplete',
          otherwise:
            "The new row in the Recipes database is titled with the name of Mum's recipe, Bacalhau à Brás, in any spelling, accents or translation.",
        },
      ),
      check(
        'recipe-has-ingredients',
        (run) => {
          const page = recipe(run);
          const properties = Object.entries(page?.properties ?? {})
            .filter(([name]) => name !== 'Name')
            .map(([, value]) => [value ?? ''].flat().join(' '))
            .join('\n');
          const text = `${page?.markdown ?? ''}\n${properties}`;
          const found = ingredients.filter((item) => item.pattern.test(text));
          return {
            pass: found.length >= 3,
            evidence: `found ${found.map((item) => item.name).join(', ') || 'none'}`,
          };
        },
        {
          failure: 'incomplete',
          otherwise:
            "The new Bacalhau à Brás row in the Recipes database holds at least three ingredients from Mum's recipe (salted cod, potatoes, eggs, onions, black olives, parsley), in any wording or language.",
        },
      ),
      check(
        'recipe-has-steps',
        (run) => {
          const text = recipe(run)?.markdown ?? '';
          return /poach/i.test(text) && /\bfr(y|ied)\b/i.test(text);
        },
        { required: false, failure: 'incomplete' },
      ),
      check(
        'existing-recipes-untouched',
        (run) => {
          const lost = seeded.filter((row, index) => {
            const page = run.apps?.notion?.pages.find((item) => item.id === rowId(index));
            return (
              !page ||
              page.archived ||
              page.markdown !== `Recipe from ${row.Source}.` ||
              JSON.stringify(page.properties) !== JSON.stringify(row)
            );
          });
          return {
            pass: !lost.length,
            evidence: lost.length
              ? `changed: ${lost.map((row) => row.Name).join(', ')}`
              : undefined,
          };
        },
        { failure: 'scope' },
      ),
      noWrites('send'),
    ];
  },
});

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { promisify } from 'node:util';

const exec = promisify(execFile);
const directory = resolve(process.argv[2] ?? '.local/nod-media');
const destination = resolve(process.argv[3] ?? 'docs/src/assets/video');
const scenes = JSON.parse(await readFile(`${directory}/scenes.json`, 'utf8'));
await mkdir(destination, { recursive: true });
const rate = 48000;
const silence = (seconds) => Buffer.alloc(Math.round(seconds * rate) * 2);
const chunks = [];
const cues = [];
let samples = 0;
for (const [index, scene] of scenes.entries()) {
  if (index) {
    const previous = chunks.pop();
    chunks.push(previous.subarray(0, previous.length - Math.round(0.45 * rate) * 2));
    samples -= Math.round(0.45 * rate);
  }
  scene.start = samples / rate;
  chunks.push(silence(0.6));
  samples += 0.6 * rate;
  for (const [part, sentence] of scene.text.split(/(?<=[.!?])\s+/).entries()) {
    const path = `${directory}/speech-${index}-${part}.aiff`;
    await exec('say', ['-v', 'Daniel', '-r', '178', '-o', path, sentence]);
    const { stdout } = await exec(
      'ffmpeg',
      ['-v', 'error', '-i', path, '-ar', String(rate), '-ac', '1', '-f', 's16le', '-'],
      { encoding: 'buffer', maxBuffer: 20_000_000 },
    );
    assert(stdout.length > 0 && stdout.length % 2 === 0);
    cues.push({ start: samples / rate, end: (samples + stdout.length / 2) / rate, text: sentence });
    chunks.push(stdout, silence(0.16));
    samples += stdout.length / 2 + Math.round(0.16 * rate);
  }
  chunks.push(silence(0.8));
  samples += 0.8 * rate;
  scene.duration = samples / rate - scene.start;
}
await writeFile(`${directory}/speech.pcm`, Buffer.concat(chunks));
await exec('ffmpeg', [
  '-v',
  'error',
  '-y',
  '-f',
  's16le',
  '-ar',
  String(rate),
  '-ac',
  '1',
  '-i',
  `${directory}/speech.pcm`,
  '-af',
  'loudnorm=I=-16:TP=-1.5:LRA=11',
  '-ar',
  String(rate),
  `${directory}/speech.wav`,
]);
const input = scenes.flatMap((scene, index) => [
  '-loop',
  '1',
  '-framerate',
  '30',
  '-t',
  String(scene.duration),
  '-i',
  `${directory}/scene-${index}.png`,
]);
const filters = scenes.map((_, index) => `[${index}:v]settb=AVTB,format=yuv420p[v${index}]`);
for (let i = 1; i < scenes.length; i++)
  filters.push(
    `[${i === 1 ? 'v0' : `mix${i - 1}`}][v${i}]xfade=transition=fade:duration=0.45:offset=${scenes[i].start}[mix${i}]`,
  );
await exec(
  'ffmpeg',
  [
    '-hide_banner',
    '-loglevel',
    'warning',
    '-y',
    '-filter_complex_threads',
    '1',
    ...input,
    '-i',
    `${directory}/speech.wav`,
    '-filter_complex',
    filters.join(';'),
    '-map',
    `[mix${scenes.length - 1}]`,
    '-map',
    `${scenes.length}:a`,
    '-c:v',
    'libx264',
    '-preset',
    'medium',
    '-crf',
    '20',
    '-pix_fmt',
    'yuv420p',
    '-c:a',
    'aac',
    '-b:a',
    '96k',
    '-movflags',
    '+faststart',
    '-shortest',
    `${destination}/trust-layer.mp4`,
  ],
  { maxBuffer: 5_000_000 },
);
const timestamp = (seconds) => {
  const value = Math.round(seconds * 1000);
  return `${String(Math.floor(value / 3600000)).padStart(2, '0')}:${String(Math.floor(value / 60000) % 60).padStart(2, '0')}:${String(Math.floor(value / 1000) % 60).padStart(2, '0')}.${String(value % 1000).padStart(3, '0')}`;
};
await writeFile(
  `${destination}/trust-layer.vtt`,
  `WEBVTT\n\n${cues.map((cue, index) => `${index + 1}\n${timestamp(cue.start)} --> ${timestamp(cue.end)}\n${cue.text}\n`).join('\n')}`,
);
await exec('ffmpeg', [
  '-v',
  'error',
  '-y',
  '-ss',
  String(scenes[1].start + 1),
  '-i',
  `${destination}/trust-layer.mp4`,
  '-frames:v',
  '1',
  '-q:v',
  '3',
  `${destination}/trust-layer-poster.jpg`,
]);
await writeFile(
  `${directory}/timing.json`,
  JSON.stringify({ scenes, cues, duration: samples / rate }, null, 2),
);
console.log(
  `Created a ${Math.round(samples / rate)} second tour with ${cues.length} caption cues.`,
);

import { readFile } from 'node:fs/promises';

export const installer = await readFile(new URL('./install.sh', import.meta.url), 'utf8');
export const windowsInstaller = await readFile(new URL('./install.ps1', import.meta.url), 'utf8');

export function installNodes() {
  return [
    {
      name: 'Install command',
      type: 'n8n-nodes-base.webhook',
      typeVersion: 2.1,
      parameters: {
        httpMethod: 'GET',
        path: 'nod/install',
        authentication: 'none',
        responseMode: 'responseNode',
        options: {},
      },
    },
    {
      name: 'Load installer',
      type: 'n8n-nodes-base.code',
      typeVersion: 2,
      parameters: {
        mode: 'runOnceForAllItems',
        language: 'javaScript',
        jsCode: `return [{json:{body:${JSON.stringify(installer)}}}];`,
      },
    },
    {
      name: 'Send response',
      type: 'n8n-nodes-base.respondToWebhook',
      typeVersion: 1.5,
      parameters: {
        respondWith: 'text',
        responseBody: '={{ $json.body }}',
        options: {
          responseCode: 200,
          enableStreaming: false,
          responseHeaders: {
            entries: [
              { name: 'Content-Type', value: 'text/plain; charset=utf-8' },
              { name: 'Cache-Control', value: 'no-store' },
              { name: 'Referrer-Policy', value: 'no-referrer' },
              { name: 'X-Content-Type-Options', value: 'nosniff' },
            ],
          },
        },
      },
    },
    {
      name: 'Windows install command',
      type: 'n8n-nodes-base.webhook',
      typeVersion: 2.1,
      parameters: {
        httpMethod: 'GET',
        path: 'nod/install-windows',
        authentication: 'none',
        responseMode: 'responseNode',
        options: {},
      },
    },
    {
      name: 'Load Windows installer',
      type: 'n8n-nodes-base.code',
      typeVersion: 2,
      parameters: {
        mode: 'runOnceForAllItems',
        language: 'javaScript',
        jsCode: `return [{json:{body:${JSON.stringify(windowsInstaller)}}}];`,
      },
    },
  ];
}

export function installWorkflowCode() {
  const declarations = installNodes().map(({ type, typeVersion, ...config }, index) => {
    const serialized = JSON.stringify(config).replace(
      JSON.stringify('={{ $json.body }}'),
      `expr(${JSON.stringify('{{ $json.body }}')})`,
    );
    return `const n${index} = ${[0, 3].includes(index) ? 'trigger' : 'node'}({type:${JSON.stringify(type)},version:${typeVersion},config:${serialized}});`;
  });
  return `import {workflow,trigger,node,expr} from '@n8n/workflow-sdk';\n${declarations.join('\n')}\nexport default workflow('nod-install','Nod Install').add(n0).to(n1).to(n2).add(n3).to(n4).to(n2);\n`;
}
